$completion=db()->prepare('SELECT a.id academic_id,aa.id academic_achievement_id,na.id non_academic_achievement_id,o.id organization_id FROM students s LEFT JOIN academic_scores a ON a.student_id=s.id LEFT JOIN academic_achievements aa ON aa.student_id=s.id LEFT JOIN non_academic_achievements na ON na.student_id=s.id LEFT JOIN organization_scores o ON o.student_id=s.id WHERE s.id=?');$completion->execute([(int)$student['id']]);$state=$completion->fetch();
if(!$state['academic_id'])redirect('student/academic.php');if(!$state['academic_achievement_id']||!$state['non_academic_achievement_id'])redirect('student/achievements.php');if(!$state['organization_id'])redirect('student/organization.php');
