function routeAverage(string $path,array $s): float {switch($path){case 'prestasi_akademik_sma':case 'prestasi_akademik_smk':return (float)($s['admission_prestasi_akademik']??$s['average_score']??0);case 'prestasi_non_akademik':return (float)($s['admission_prestasi_nonakademik']??$s['average_score']??0);case 'afirmasi_sma':return (float)($s['admission_afirmasi']??$s['average_score']??0);case 'zonasi_sma':return (float)($s['admission_zonasi']??$s['average_score']??0);case 'tahap_kedua_sma':return (float)($s['admission_tahap_kedua']??$s['average_score']??0);case 'afirmasi_tahap_kedua_smk':$a=(float)($s['admission_afirmasi']??0);$b=(float)($s['admission_tahap_kedua']??0);return $a&&$b?($a+$b)/2:($a?:($b?:($s['average_score']??0)));}return (float)($s['average_score']??0);}
function routeCapacity(string $path,array $s): ?int { $keys=['prestasi_akademik_sma'=>'capacity_prestasi_akademik','prestasi_akademik_smk'=>'capacity_prestasi_akademik','prestasi_non_akademik'=>'capacity_prestasi_nonakademik','afirmasi_sma'=>'capacity_afirmasi','zonasi_sma'=>'capacity_zonasi','tahap_kedua_sma'=>'capacity_tahap_kedua']; if($path==='afirmasi_tahap_kedua_smk'){ $a=$s['capacity_afirmasi']??null; $b=$s['capacity_tahap_kedua']??null; return $a !== null && $b !== null ? (int)round(((int)$a+(int)$b)/2) : ($a !== null ? (int)$a : ($b !== null ? (int)$b : null)); } $key=$keys[$path]??null; return $key!==null && ($s[$key]??null)!==null ? (int)$s[$key] : (($s['capacity']??null)!==null ? (int)$s['capacity'] : null); }
