 $csv=__DIR__.'/../SMKSMA404.csv';if(is_readable($csv)&&($h=fopen($csv,'r'))){$headers=fgetcsv($h,0,';');while(($r=fgetcsv($h,0,';'))!==false){if(count($r)<20||trim((string)($r[0]??''))==='')continue;$capacityIndex=null;if(in_array($path,['prestasi_akademik_sma','prestasi_akademik_smk'],true))$capacityIndex=20;elseif($path==='prestasi_non_akademik')$capacityIndex=21;elseif($path==='tahap_kedua_sma')$capacityIndex=22;elseif($path==='afirmasi_sma')$capacityIndex=23;elseif($path==='zonasi_sma')$capacityIndex=24;$capacityValue=($capacityIndex!==null && isset($r[$capacityIndex]))?preg_replace('/[^0-9]/','',$r[$capacityIndex]):null;$schools[]=['npsn'=>$r[0],'name'=>$r[1],'address'=>$r[2],'domisili'=>$r[13],'school_type'=>stripos(trim($r[1]),'SMK')===0?'SMK':'SMA','average_score'=>(float)($r[14]??0),'capacity'=>$capacityValue!==null&&$capacityValue!==''?(int)$capacityValue:null,'capacity_prestasi_akademik'=>csvCapacity($r[20]??null),'capacity_prestasi_nonakademik'=>csvCapacity($r[21]??null),'capacity_tahap_kedua'=>csvCapacity($r[22]??null),'capacity_afirmasi'=>csvCapacity($r[23]??null),'capacity_zonasi'=>csvCapacity($r[24]??null),'accreditation'=>$r[19]??'','admission_prestasi_akademik'=>(float)($r[14]??0),'admission_prestasi_nonakademik'=>(float)($r[15]??0),'admission_tahap_kedua'=>(float)($r[16]??0),'admission_afirmasi'=>(float)($r[17]??0),'admission_zonasi'=>(float)($r[18]??0),'competencies'=>array_values(array_filter(array_slice($r,3,10),fn($v)=>trim((string)$v)!==''))];$schools[array_key_last($schools)]['admission_average']=routeAverage($path,$schools[array_key_last($schools)]);$schools[array_key_last($schools)]['capacity']=routeCapacity($path,$schools[array_key_last($schools)]);}fclose($h);}
